const MATERIAL_SUGGESTIONS = [
  "PLA",
  "PLA Matte",
  "PLA Silk",
  "PETG",
  "PETG HF",
  "ABS",
  "ASA",
  "TPU 95A",
  "PC",
  "PA-CF",
  "PVA",
  "HIPS",
];

export function modelTab(thingport) {
  const { root, shared, ui, t, context, language } = thingport;
  addStyle(root, BASE_CSS + TAB_CSS);
  const box = document.createElement("div");
  box.className = `fs-ui fs-tab ${themeClass(thingport)}`;
  root.append(box);
  const materialsId = `fs-materials-${newId()}`;

  let data = null;
  let problem = null;
  // The rows being edited, each with the hex as typed and the last colour it read as.
  let draft = null;
  let saving = false;
  let fresh = null;
  let closed = false;
  let reads = 0;

  async function load() {
    const read = ++reads;
    try {
      const next = await loadForModel(thingport, context.modelId, context.fileId);
      if (closed || read !== reads) return;
      data = next;
      problem = null;
    } catch (error) {
      if (closed || read !== reads) return;
      problem = error?.message || String(error);
    }
    // A change from elsewhere mid-edit shows in the people's columns, leaving the rows being typed in alone, unless
    // the people changed: then the columns are drawn again, the rows from what's typed.
    if (draft && data && peopleOf(data) === drawnPeople) updateMatches();
    else render();
  }

  // Whose columns the grid has, so a change that adds or takes one away draws it whole.
  let drawnPeople = "";
  const peopleOf = (shown) => shown.everyone.map((person) => person.key).join("|");

  const draftNeeds = () =>
    needsFor(data.model, context.fileId, {
      filaments: draft.map((row) => ({ type: row.type.trim() || null, color: row.color, grams: row.grams })),
    });
  const shownNeeds = () => (draft ? draftNeeds() : data.needs);

  function cell(match) {
    if (!match)
      return `<span class="fs-no" aria-hidden="true">—</span><span class="fs-sr">${escapeHtml(t("grid.doesnt"))}</span>`;
    const name = escapeHtml(spoolLabel(t, match.entry.value));
    const mark =
      match.grade === "same"
        ? `<span class="fs-has">${icon("check")}${escapeHtml(t("grid.hasIt"))}</span>`
        : `<span class="fs-near">≈ ${escapeHtml(t("grid.close"))}</span>`;
    return `${mark}<small title="${name}">${name}</small>`;
  }

  const countPill = (have, count) =>
    `<span class="fs-pill ${have === count ? "fs-all" : have ? "fs-some" : "fs-none"}">${escapeHtml(t("grid.of", { have, count }))}</span>`;

  function editor(row, index) {
    const palette = PALETTE.map(
      ([name, hex]) =>
        `<button type="button" role="radio" aria-checked="${row.color === hex}" data-pick="${index}" data-hex="${hex}" style="--fs-c:${hex}" aria-label="${escapeHtml(t(`colour.${name}`))}" title="${escapeHtml(t(`colour.${name}`))}"></button>`,
    ).join("");
    const anyColour = escapeHtml(t("edit.anyColour"));
    return `
      <div class="fs-ed">
        <label class="fs-ed-sw" title="${escapeHtml(t("edit.pick"))}">${swatch(row.color, "fs-l")}<input type="color" data-native="${index}" value="${(row.color ?? "#FFFFFF").toLowerCase()}" aria-label="${escapeHtml(t("edit.pick"))}"></label>
        <input class="fs-input fs-small fs-type" data-type="${index}" list="${materialsId}" value="${escapeHtml(row.type)}" maxlength="60" placeholder="${escapeHtml(t("edit.material"))}" aria-label="${escapeHtml(t("edit.material"))}">
        <input class="fs-input fs-small fs-mono fs-hex" data-hex="${index}" value="${escapeHtml(row.hex)}" maxlength="9" placeholder="${anyColour}" aria-label="${escapeHtml(t("edit.hex"))}" aria-invalid="${row.hex.trim() !== "" && !normaliseHex(row.hex)}">
      </div>
      <div class="fs-palette fs-ed-pal" role="radiogroup" aria-label="${escapeHtml(t("edit.colour"))}">${palette}<button type="button" role="radio" class="fs-any" aria-checked="${row.color === null}" data-pick="${index}" data-hex="" aria-label="${anyColour}" title="${anyColour}"></button></div>`;
  }

  function grid(needs, match) {
    const { everyone } = data;
    const columns = `minmax(230px, 1.6fr) repeat(${everyone.length}, minmax(110px, 150px))${draft ? " 40px" : ""}`;
    const head = everyone
      .map(
        (person) =>
          `<div role="columnheader" class="fs-c fs-mid">${avatar(t, person)}<span>${escapeHtml(personName(t, person))}</span></div>`,
      )
      .join("");
    const rows = needs
      .map((need, i) => {
        const row = draft?.[i];
        const first = row
          ? editor(row, i)
          : `${swatch(need.color)}<span><b>${escapeHtml(filamentLabel(t, need))}</b><small>${escapeHtml(filamentDetail(t, need, language))}</small></span>`;
        const cells = match.rows[i].cells
          .map((found, j) => `<div role="cell" class="fs-c fs-mid" data-cell="${i}:${j}">${cell(found)}</div>`)
          .join("");
        const remove = row
          ? `<div role="cell" class="fs-c"><button type="button" class="fs-icon-btn" data-remove="${i}" aria-label="${escapeHtml(t("edit.remove"))}" title="${escapeHtml(t("edit.remove"))}">${icon("delete")}</button></div>`
          : "";
        return `<div role="row" class="fs-r${row && row.id === fresh ? " fs-row-new" : ""}"><div role="rowheader" class="fs-c fs-need">${first}</div>${cells}${remove}</div>`;
      })
      .join("");
    const grams = needs.reduce((sum, need) => sum + (need.grams ?? 0), 0);
    const lead = draft
      ? `<button type="button" class="fs-btn fs-small" data-act="add"${draft.length >= MAX_FILAMENTS ? " disabled" : ""}>${icon("add")}${escapeHtml(t("edit.add"))}</button>`
      : grams
        ? escapeHtml(t("grid.total", { grams: formatGrams(grams, language) }))
        : "";
    const counts = match.counts
      .map((have, j) => `<div role="cell" class="fs-c fs-mid" data-count="${j}">${countPill(have, match.count)}</div>`)
      .join("");
    return `
      <div class="fs-wrap"><div class="fs-grid${draft ? " fs-editing" : ""}" role="table" aria-label="${escapeHtml(t("modelPage.tab"))}" style="grid-template-columns:${columns}">
        <div role="row" class="fs-r fs-head"><div role="columnheader" class="fs-c">${escapeHtml(t("grid.needs"))}</div>${head}${draft ? `<div role="columnheader" class="fs-c"><span class="fs-sr">${escapeHtml(t("edit.remove"))}</span></div>` : ""}</div>
        ${rows}
        <div role="row" class="fs-r fs-foot"><div role="cell" class="fs-c">${lead}</div>${counts}${draft ? '<div role="cell" class="fs-c"></div>' : ""}</div>
      </div></div>`;
  }

  function together(match) {
    if (!data.spools.length)
      return `<div class="fs-together fs-none" data-summary>${icon("shelf")}<span>${escapeHtml(t("sum.noSpools"))}</span><button type="button" class="fs-btn fs-small" data-act="open">${escapeHtml(t("tab.openShelf"))}</button></div>`;
    if (!match.count) return "";
    const kind = tone(match);
    return `<div class="fs-together ${kind}" data-summary>${icon(kind === "fs-all" ? "check" : "warn")}<span>${escapeHtml(summary(t, match, data.everyone))}</span></div>`;
  }

  function toolbar() {
    const { model, file, edit } = data;
    const profiles = model.files.filter((other) => other.profile || other.id === file?.id);
    const title = (other) => other.profile?.name || other.name;
    let picker = "";
    if (profiles.length > 1)
      picker = `<label class="fs-profile">${icon("profile")}<span class="fs-sr">${escapeHtml(t("tab.profile"))}</span><select class="fs-select fs-small" data-act="profile"${draft ? " disabled" : ""}>${profiles
        .map(
          (other) =>
            `<option value="${escapeHtml(other.id)}"${other.id === file?.id ? " selected" : ""}>${escapeHtml(title(other))}</option>`,
        )
        .join("")}</select></label>`;
    else if (file?.profile)
      picker = `<span class="fs-profile" title="${escapeHtml(t("tab.profile"))}">${icon("profile")}<span class="fs-profile-name">${escapeHtml(title(file))}</span></span>`;
    const edited =
      edit && !draft
        ? `<span class="fs-edited">${icon("edit")}${escapeHtml(edit.mine ? t("tab.editedByYou") : t("tab.editedBy", { name: edit.user?.name ?? "?" }))}</span><button type="button" class="fs-btn fs-quiet fs-small" data-act="reset">${icon("reset")}${escapeHtml(t("tab.reset"))}</button>`
        : "";
    const editButton =
      draft || !shownNeeds().length
        ? ""
        : `<button type="button" class="fs-btn fs-outline fs-small" data-act="edit">${icon("edit")}${escapeHtml(t("tab.edit"))}</button>`;
    return `<div class="fs-tools">${picker}${edited}<span class="fs-spacer"></span><button type="button" class="fs-btn fs-quiet fs-small" data-act="open">${icon("shelf")}${escapeHtml(t("tab.openShelf"))}</button>${editButton}</div>`;
  }

  function render() {
    box.setAttribute("aria-busy", String(!data && !problem));
    drawnPeople = data ? peopleOf(data) : "";
    if (!data) {
      box.innerHTML = problem
        ? `<div class="fs-problem">${icon("warn")}<span>${escapeHtml(t("tab.failed", { error: problem }))}</span><button type="button" class="fs-btn fs-small" data-act="retry">${escapeHtml(t("tab.retry"))}</button></div>`
        : `<span class="fs-sr">${escapeHtml(t("loading"))}</span>${'<div class="fs-skel-row" aria-hidden="true"><span class="fs-skel"></span><span class="fs-skel"></span><span class="fs-skel"></span><span class="fs-skel"></span></div>'.repeat(3)}`;
      return;
    }
    const needs = shownNeeds();
    const match = matchAll(needs, data.spools, data.everyone);
    let body;
    if (!needs.length && !draft)
      body = `<div class="fs-blank">${swatch(null, "fs-l")}<span>${escapeHtml(t(data.edit ? "empty.noneSet" : "empty.noFilaments"))}</span><button type="button" class="fs-btn fs-outline fs-small" data-act="start">${icon("add")}${escapeHtml(t("edit.add"))}</button></div>`;
    else
      body =
        grid(needs, match) +
        (draft
          ? `<datalist id="${materialsId}">${MATERIAL_SUGGESTIONS.map((name) => `<option value="${name}"></option>`).join("")}</datalist>
             <div class="fs-actions"><button type="button" class="fs-btn fs-quiet fs-small" data-act="cancel"${saving ? " disabled" : ""}>${escapeHtml(t("edit.cancel"))}</button><button type="button" class="fs-btn fs-primary fs-small" data-act="save"${saving ? " disabled" : ""}>${escapeHtml(t("edit.save"))}</button></div>`
          : "");
    box.innerHTML = toolbar() + body + (needs.length ? together(match) : "");
    // While a save goes, the rows are what it sends: nothing in them changes until it's done.
    if (saving) for (const control of box.querySelectorAll(".fs-grid input, .fs-grid button")) control.disabled = true;
  }

  /** While editing: the people's columns, the counts and the summary follow what's typed, the inputs left alone. */
  function updateMatches() {
    const needs = draftNeeds();
    const match = matchAll(needs, data.spools, data.everyone);
    match.rows.forEach((row, i) =>
      row.cells.forEach((found, j) => {
        const target = box.querySelector(`[data-cell="${i}:${j}"]`);
        if (target) target.innerHTML = cell(found);
      }),
    );
    match.counts.forEach((have, j) => {
      const target = box.querySelector(`[data-count="${j}"]`);
      if (target) target.innerHTML = countPill(have, match.count);
    });
    const old = box.querySelector("[data-summary]");
    const next = together(match);
    if (old && next) old.outerHTML = next;
    else if (old) old.remove();
    else if (next) box.insertAdjacentHTML("beforeend", next);
  }

  /** One edited row's colour, shown in its swatch, inputs and palette. */
  function showColour(index, { hexInput = true } = {}) {
    const row = draft[index];
    const cellBox = box.querySelector(`[data-type="${index}"]`)?.closest(".fs-need");
    if (!cellBox) return;
    cellBox.querySelector(".fs-sw").outerHTML = swatch(row.color, "fs-l");
    if (row.color) cellBox.querySelector("[data-native]").value = row.color.toLowerCase();
    const hex = cellBox.querySelector("[data-hex]");
    if (hexInput) hex.value = row.hex;
    hex.setAttribute("aria-invalid", String(row.hex.trim() !== "" && !normaliseHex(row.hex)));
    for (const option of cellBox.querySelectorAll("[data-pick]"))
      option.setAttribute("aria-checked", String((option.dataset.hex || null) === row.color));
  }

  const blankRow = () => ({ id: newId(), type: "PLA", hex: "#FFFFFF", color: "#FFFFFF", grams: null });

  function startEdit(withRow = false) {
    draft = data.needs.map((need) => ({
      id: newId(),
      type: need.type ?? "",
      hex: need.color ?? "",
      color: need.color,
      grams: need.grams,
    }));
    if ((withRow || !draft.length) && draft.length < MAX_FILAMENTS) {
      const row = blankRow();
      draft.push(row);
      fresh = row.id;
    }
    render();
    box.querySelector("[data-type]")?.focus();
  }

  const failed = (error) => ui.toast(t("toast.failed", { error: error?.message || String(error) }), "error");

  async function save() {
    const bad = draft.findIndex((row) => row.hex.trim() !== "" && !normaliseHex(row.hex));
    if (bad >= 0) return box.querySelector(`[data-hex="${bad}"]`)?.focus();
    const filaments = draft.map((row) => ({
      type: row.type.trim() || null,
      color: row.hex.trim() ? normaliseHex(row.hex) : null,
      grams: row.grams ?? null,
    }));
    saving = true;
    render();
    try {
      await shared.set(
        needsKey(context.modelId, data.profile),
        { profile: data.profile, filaments },
        { model: context.modelId },
      );
      draft = null;
      await load();
    } catch (error) {
      failed(error);
    } finally {
      saving = false;
      if (!closed) {
        render();
        // Saved, so the editor's gone: back to the button that opened it.
        if (!draft) box.querySelector('[data-act="edit"]')?.focus();
      }
    }
  }

  async function reset() {
    const sure = await ui.confirm({
      title: t("reset.title"),
      message: t("reset.message"),
      confirmLabel: t("tab.reset"),
    });
    if (!sure || closed) return;
    try {
      await shared.set(
        needsKey(context.modelId, data.profile),
        { profile: data.profile, filaments: null },
        { model: context.modelId },
      );
      await load();
    } catch (error) {
      failed(error);
    }
  }

  box.addEventListener("click", (event) => {
    const target = event.target.closest("button");
    if (!target || target.disabled) return;
    const act = target.dataset.act;
    if (act === "open") return ui.openWindow();
    // A save owns the rows until it's done.
    if (saving) return;
    if (act === "edit") return startEdit();
    if (act === "start") return startEdit(true);
    if (act === "retry") return void load();
    if (act === "reset") return void reset();
    if (act === "save") return void save();
    if (act === "cancel") {
      draft = null;
      render();
      return void box.querySelector('[data-act="edit"]')?.focus();
    }
    if (act === "add") {
      if (draft.length >= MAX_FILAMENTS) return;
      const row = blankRow();
      draft.push(row);
      fresh = row.id;
      render();
      return box.querySelector(`[data-type="${draft.length - 1}"]`)?.focus();
    }
    if (target.dataset.remove !== undefined) {
      const index = Number(target.dataset.remove);
      draft.splice(index, 1);
      fresh = null;
      render();
      return (
        box.querySelector(`[data-remove="${Math.min(index, draft.length - 1)}"]`) ??
        box.querySelector('[data-act="add"]')
      )?.focus();
    }
    if (target.dataset.pick !== undefined) {
      const index = Number(target.dataset.pick);
      draft[index].color = target.dataset.hex || null;
      draft[index].hex = target.dataset.hex;
      showColour(index);
      updateMatches();
    }
  });

  box.addEventListener("input", (event) => {
    if (saving) return;
    const input = event.target;
    if (input.dataset.type !== undefined) {
      draft[Number(input.dataset.type)].type = input.value;
      return updateMatches();
    }
    if (input.dataset.hex !== undefined) {
      const index = Number(input.dataset.hex);
      const row = draft[index];
      row.hex = input.value;
      if (!input.value.trim()) row.color = null;
      else row.color = normaliseHex(input.value) ?? row.color;
      showColour(index, { hexInput: false });
      return updateMatches();
    }
    if (input.dataset.native !== undefined) {
      const index = Number(input.dataset.native);
      draft[index].color = normaliseHex(input.value);
      draft[index].hex = draft[index].color;
      showColour(index);
      updateMatches();
    }
  });

  box.addEventListener("change", (event) => {
    if (event.target.dataset.act === "profile") ui.selectFile(event.target.value);
  });

  box.addEventListener("keydown", (event) => {
    if (!draft || saving) return;
    if (event.key === "Escape") {
      event.stopPropagation();
      draft = null;
      render();
      box.querySelector('[data-act="edit"]')?.focus();
    } else if (event.key === "Enter" && event.target.matches("input:not([type=color])")) {
      event.preventDefault();
      void save();
    }
  });

  const stop =
    shared.onChange?.(() => {
      forgetReads();
      void load();
    }) ?? (() => {});
  // Others' changes, from their own browsers, are read afresh too, not from what a part read a moment ago.
  const stopReturn = onReturn(() => {
    forgetReads();
    void load();
  });
  render();
  void load();

  return () => {
    closed = true;
    stop();
    stopReturn();
  };
}

// ---- badge.js ----

// The mark on a model's picture: a ring filled by how many of the filaments the household has, the first few
// colours inside it, and a popover naming who has each.


const BADGE_CSS = `
.fs-badge {
  --fs-ring: rgba(255, 255, 255, 0.35);
  --fs-fill: 0%;
  width: 44px; height: 44px; border-radius: 50% !important; display: flex; align-items: center; justify-content: center;
  background: conic-gradient(var(--fs-ring) 0 var(--fs-fill), rgba(255, 255, 255, 0.3) var(--fs-fill) 100%);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.35); animation: fs-pop 180ms ease-out; transition: transform 150ms;
}
.fs-badge:hover { transform: scale(1.06); }
.fs-badge:focus-visible { outline-color: #fff; }
.fs-badge.fs-all { --fs-ring: var(--tp-success); }
.fs-badge.fs-some { --fs-ring: var(--tp-warning); }
.fs-badge > span {
  width: 36px; height: 36px; border-radius: 50% !important; display: flex; align-items: center; justify-content: center;
  background: rgba(0, 0, 0, 0.7);
}
.fs-stack { display: inline-flex; }
.fs-stack .fs-sw { width: 12px; height: 12px; box-shadow: none; border: 1.5px solid rgba(0, 0, 0, 0.7); }
.fs-stack .fs-sw.fs-any { border: 1.5px dashed rgba(255, 255, 255, 0.7); }
.fs-stack .fs-sw + .fs-sw { margin-left: -5px; }
`;

const POPOVER_CSS = `
.fs-pop { display: flex; flex-direction: column; gap: 8px; padding: 12px 14px; }
.fs-pop-head { display: flex; align-items: center; gap: 8px; margin: 0; font-size: 13px; font-weight: 600; }
.fs-pop-head svg { width: 16px; height: 16px; color: var(--tp-text-muted); }
.fs-pop-head .fs-icon-btn { margin-left: auto; width: 24px; height: 24px; }
.fs-pop-head .fs-icon-btn svg { width: 16px; height: 16px; }
.fs-pop-rows { display: flex; flex-direction: column; gap: 6px; max-height: 300px; overflow-y: auto; margin: 0; padding: 0; list-style: none; }
.fs-pop-row { display: grid; grid-template-columns: 20px 1fr auto; gap: 8px; align-items: center; font-size: 12.5px; animation: fs-in 160ms ease-out both; }
.fs-pop-row > span { min-width: 0; }
.fs-pop-row small { display: block; font-size: 11px; }
.fs-owners { display: flex; align-items: center; gap: 6px; }
.fs-owner { display: inline-flex; align-items: center; gap: 2px; }
.fs-owners .fs-av { width: 18px; height: 18px; font-size: 9px; }
.fs-nobody { font-size: 11px; font-weight: 600; color: var(--tp-error); }
.fs-pop-foot { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding-top: 8px; border-top: 1px solid var(--tp-divider); }
.fs-pop-sum { display: inline-flex; align-items: center; gap: 5px; font-size: 12px; }
.fs-pop-sum svg { width: 16px; height: 16px; }
.fs-pop-sum.fs-all svg { color: var(--fs-same); }
.fs-pop-sum.fs-some svg { color: var(--fs-close); }
.fs-pop-sum.fs-none svg { color: var(--tp-text-muted); }
.fs-pop-foot .fs-btn { padding: 0 4px 0 8px; gap: 0; }
`;

export function modelImage(thingport) {
  const { root, shared, ui, t, context, language } = thingport;
  const style = document.createElement("style");
  style.textContent = BASE_CSS + BADGE_CSS;
  const button = document.createElement("button");
  button.type = "button";
  button.setAttribute("aria-haspopup", "dialog");
  button.setAttribute("aria-expanded", "false");
  const shell = document.createElement("div");
  shell.className = `fs-ui ${themeClass(thingport)}`;
  shell.append(button);

  let data = null;
  let popover = null;
  let redraw = null;
  let closed = false;
  let reads = 0;
  const titleId = `fs-pop-title-${Math.random().toString(36).slice(2, 8)}`;

  async function load() {
    const read = ++reads;
    try {
      const next = await loadForModel(thingport, context.modelId, context.fileId);
      if (closed || read !== reads) return;
      data = next;
    } catch {
      // A mark on a picture says nothing rather than an error; the tab says what went wrong.
      if (closed || read !== reads) return;
      data = null;
    }
    render();
  }

  function render() {
    if (!data?.needs.length) {
      popover?.close();
      root.replaceChildren();
      return;
    }
    const { match, needs } = data;
    const label = t("badge.label", { summary: shortSummary(t, match) });
    button.className = `fs-badge ${tone(match)}`;
    button.style.setProperty("--fs-fill", `${(match.have / match.count) * 100}%`);
    button.setAttribute("aria-label", label);
    button.title = label;
    button.innerHTML = `<span><span class="fs-stack">${needs
      .slice(0, 3)
      .map((need) => swatch(need.color))
      .join("")}</span></span>`;
    if (!root.contains(button)) root.replaceChildren(style, shell);
    redraw?.();
  }

  function owners(cells) {
    const has = cells
      .map((found, j) => found && { found, person: data.everyone[j] })
      .filter(Boolean)
      .map(({ found, person }) => {
        const close = found.grade === "close";
        const key = `pop.${close ? "close" : "has"}${person.mine ? "You" : ""}`;
        const said = escapeHtml(t(key, { name: personName(t, person) }));
        return `<span class="fs-owner" title="${said}">${avatar(t, person)}${close ? '<span class="fs-near" aria-hidden="true">≈</span>' : ""}<span class="fs-sr">${said}</span></span>`;
      });
    return has.length ? has.join("") : `<span class="fs-nobody">${escapeHtml(t("pop.nobody"))}</span>`;
  }

  function drawPopover(box) {
    const { match } = data;
    const kind = tone(match);
    const html = `
      <h3 class="fs-pop-head" id="${titleId}">${icon("palette")}<span>${escapeHtml(t("pop.title"))}</span><button type="button" class="fs-icon-btn" data-act="close" aria-label="${escapeHtml(t("pop.closeLabel"))}" title="${escapeHtml(t("pop.closeLabel"))}">${icon("close")}</button></h3>
      <ul class="fs-pop-rows">${match.rows
        .map(
          ({ need, cells }, i) =>
            `<li class="fs-pop-row" style="animation-delay:${Math.min(i, 6) * 25}ms">${swatch(need.color)}<span>${escapeHtml(filamentLabel(t, need))}<small>${escapeHtml(filamentDetail(t, need, language))}</small></span><span class="fs-owners">${owners(cells)}</span></li>`,
        )
        .join("")}</ul>
      <div class="fs-pop-foot"><span class="fs-pop-sum ${kind}">${icon(kind === "fs-all" ? "check" : "warn")}<span>${escapeHtml(shortSummary(t, match))}</span></span><button type="button" class="fs-btn fs-small" data-act="details">${escapeHtml(t("pop.details"))}${icon("chevron")}</button></div>`;
    // Drawn again only when it says something new, and then with the focus where it was, so a change elsewhere
    // neither replays the rows coming in nor drops a keyboard user back to the page's start.
    if (html === box.dataset.html) return;
    const focused = box.contains(document.activeElement) ? document.activeElement.dataset.act : null;
    box.dataset.html = html;
    box.innerHTML = html;
    if (focused) box.querySelector(`[data-act="${focused}"]`)?.focus();
  }

  button.addEventListener("click", () => {
    if (popover) return popover.close();
    popover = ui.popover(
      button,
      (popRoot) => {
        addStyle(popRoot, BASE_CSS + POPOVER_CSS);
        const box = document.createElement("div");
        box.className = `fs-ui fs-pop ${themeClass(thingport)}`;
        box.setAttribute("role", "group");
        box.setAttribute("aria-labelledby", titleId);
        popRoot.append(box);
        box.addEventListener("click", (event) => {
          const act = event.target.closest("button")?.dataset.act;
          if (act === "close") popover?.close();
          if (act === "details") {
            popover?.close();
            ui.showTab();
          }
        });
        redraw = () => drawPopover(box);
        redraw();
        button.setAttribute("aria-expanded", "true");
        return () => {
          redraw = null;
          popover = null;
          button.setAttribute("aria-expanded", "false");
        };
      },
      { placement: "bottom", width: 330 },
    );
  });

  const stop =
    shared.onChange?.(() => {
      forgetReads();
      void load();
    }) ?? (() => {});
  // Others' changes, from their own browsers, are read afresh too, not from what a part read a moment ago.
  const stopReturn = onReturn(() => {
    forgetReads();
    void load();
  });
  void load();

  return () => {
    closed = true;
    stop();
    stopReturn();
    popover?.close();
  };
}

// ---- window.js ----

// The window: the household's spools as cards, filtered by person, material, brand and colour, each person's own to
// add, change and take off the shelf. Opened on a model, it also offers to add what that model needs.


const MATERIAL_CHOICES = [...MATERIALS, "other"];
const AMOUNT_CHOICES = [...AMOUNTS, "grams"];
// Below this many grams a weighed spool's bar warns, as "Nearly out" does.
const LOW_GRAMS = 150;

export default function mount(thingport) {
  const { root, shared, models, ui, t, labels, language, context } = thingport;
  addStyle(root, BASE_CSS);
  const shell = root.querySelector(".fs");
  shell.classList.add(themeClass(thingport));
  const $ = (id) => root.querySelector(`#fs-${id}`);
  const peopleBar = $("people");
  const materialsBar = $("materials");
  const brandSelect = $("brand");
  const colourButton = $("colour");
  const needsStrip = $("needs");
  const cards = $("cards");
  const empty = $("empty");
  const veil = $("veil");
  const form = $("dialog");
  const body = $("dialog-body");
  const input = (name) => $(`f-${name}`);

  // Everything read under spool:, as stored; validated where it's used.
  let entries = null;
  let needEntries = [];
  // Whether the edits about the model have been read: until then its needs aren't known, rather than the profile's.
  let needsRead = false;
  let model = null;
  let everyone = [];
  let problem = null;
  const filter = { who: null, material: null, brand: null, colour: null };
  // What the bar's menus list, from the last draw.
  let moreMaterials = [];
  let colours = [];
  let needs = [];
  let menu = null;
  let dialog = null;
  let closed = false;
  let reads = 0;
  // Writes going, and writes started or ended: a read either overlaps is dropped, and the one after them shows.
  let pending = 0;
  let writes = 0;
  // Cards drawn last time, so only new ones come in with an animation.
  let drawn = new Set();
  const inTurn = writesInTurn();
  const safely = (fn) => toastFailures(thingport, fn, () => closed);

  async function load() {
    const read = ++reads;
    const at = writes;
    const [spoolList, needList, picked] = await Promise.all([
      readAll(shared, { prefix: SPOOL }),
      context.modelId ? readAll(shared, { prefix: NEEDS, model: context.modelId }).catch(() => null) : [],
      context.modelId && !model ? models.get(context.modelId).catch(() => null) : model,
    ]);
    if (closed || read !== reads || pending || at !== writes) return;
    entries = spoolList;
    // A failed read of the edits keeps the last that worked: as none, an edit would read as the profile's list.
    if (needList) {
      needEntries = needList;
      needsRead = true;
    }
    model = picked;
    problem = null;
    render();
  }

  async function refresh() {
    try {
      await load();
    } catch (error) {
      if (closed) return;
      const message = error?.message || String(error);
      if (entries === null) {
        problem = message;
        render();
      } else ui.toast(t("toast.failed", { error: message }), "error");
    }
  }

  /** Saves through `fn` in its key's turn, then reads the shelf again once nothing else is saving. */
  async function write(key, fn) {
    pending += 1;
    writes += 1;
    try {
      return await inTurn(key, fn);
    } finally {
      pending -= 1;
      writes += 1;
      if (!pending && !closed) void refresh();
    }
  }

  const reader = () => {
    const me = everyone[0];
    return me?.id ? { id: me.id, name: me.name, avatarUrl: me.avatarUrl } : null;
  };

  // ---- drawing ----

  function render() {
    const loading = entries === null;
    // Nothing to add to until the shelf is read: a spool added before would be lost.
    $("add").disabled = loading;
    cards.setAttribute("aria-busy", String(loading && !problem));
    if (loading) {
      showEmpty(problem ? { title: t("shelf.failed"), hint: problem, act: "retry", label: t("shelf.retry") } : null);
      cards.hidden = Boolean(problem);
      if (!problem)
        cards.innerHTML =
          '<li class="fs-card fs-skel-card" aria-hidden="true"><span class="fs-skel"></span></li>'.repeat(8);
      return;
    }
    const spools = spoolsOf(entries);
    everyone = people([...entries, ...needEntries], thingport.user ?? null);
    if (filter.who && !everyone.some((person) => person.key === filter.who)) filter.who = null;
    const theirs = filter.who ? spools.filter((entry) => ownerKey(entry) === filter.who) : spools;
    drawPeople();
    drawMaterials(theirs);
    drawBrands(spools);
    drawColours(theirs);
    drawNeeds(spools);
    drawCards(spools, theirs);
  }

  function drawPeople() {
    peopleBar.hidden = everyone.length < 2;
    const chip = (key, label, person) =>
      `<button type="button" class="fs-chip${person ? "" : " fs-plain"}" data-who="${escapeHtml(key)}" aria-pressed="${(filter.who ?? "") === key}">${person ? avatar(t, person) : ""}<span>${escapeHtml(label)}</span></button>`;
    peopleBar.innerHTML = [
      chip("", t("people.everyone")),
      ...everyone.map((person) => chip(person.key, personName(t, person), person)),
    ].join("");
  }

  function drawMaterials(theirs) {
    const counts = new Map();
    for (const entry of theirs) {
      const name = family(entry.value.material);
      counts.set(name, (counts.get(name) ?? 0) + 1);
    }
    const ordered = [...counts].toSorted((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));
    let shown = ordered.slice(0, 4);
    const chosen = filter.material;
    if (chosen && !shown.some(([name]) => name === chosen))
      shown = [...shown.slice(0, 3), [chosen, counts.get(chosen) ?? 0]];
    moreMaterials = ordered.filter(([name]) => !shown.some(([other]) => other === name));
    materialsBar.hidden = ordered.length < 2 && !chosen;
    materialsBar.innerHTML = [
      `<button type="button" data-material="" aria-pressed="${!chosen}">${escapeHtml(t("filter.all"))}</button>`,
      ...shown.map(
        ([name, count]) =>
          `<button type="button" data-material="${escapeHtml(name)}" aria-pressed="${chosen === name}">${escapeHtml(name)}<b>${count}</b></button>`,
      ),
      moreMaterials.length
        ? `<button type="button" data-more aria-haspopup="menu" aria-expanded="false">${escapeHtml(t("filter.more"))}${icon("drop")}</button>`
        : "",
    ].join("");
  }

  function drawBrands(spools) {
    const brands = new Map();
    for (const entry of spools) {
      const brand = entry.value.brand.trim();
      if (brand && !brands.has(brand.toLowerCase())) brands.set(brand.toLowerCase(), brand);
    }
    if (filter.brand && !brands.has(filter.brand)) filter.brand = null;
    brandSelect.hidden = brands.size < 2 && !filter.brand;
    brandSelect.innerHTML = [
      `<option value="">${escapeHtml(t("filter.anyBrand"))}</option>`,
      ...[...brands]
        .toSorted((a, b) => a[1].localeCompare(b[1]))
        .map(
          ([key, label]) =>
            `<option value="${escapeHtml(key)}"${filter.brand === key ? " selected" : ""}>${escapeHtml(label)}</option>`,
        ),
    ].join("");
  }

  function drawColours(theirs) {
    colours = PALETTE.filter(([name]) => theirs.some((entry) => bucketOf(entry.value.color) === name));
    const chosen = PALETTE.find(([name]) => name === filter.colour);
    colourButton.hidden = colours.length < 2 && !chosen;
    colourButton.classList.toggle("fs-on", Boolean(chosen));
    colourButton.innerHTML = chosen
      ? `${swatch(chosen[1], "fs-s")}<span>${escapeHtml(t(`colour.${chosen[0]}`))}</span>${icon("drop")}`
      : `${icon("palette")}<span>${escapeHtml(t("filter.anyColour"))}</span>${icon("drop")}`;
    colourButton.setAttribute(
      "aria-label",
      `${t("filter.colour")}: ${chosen ? t(`colour.${chosen[0]}`) : t("filter.anyColour")}`,
    );
  }

  function drawNeeds(spools) {
    needs =
      model && needsRead
        ? needsFor(model, context.fileId, currentEdit(needEntries, profileKey(pickFile(model, context.fileId))))
        : [];
    needsStrip.hidden = !needs.length;
    if (!needs.length) return;
    const missing = new Set(missingOnShelf(needs, spools));
    const chips = needs.map((need, i) => {
      const label = escapeHtml(filamentLabel(t, need));
      return missing.has(need)
        ? `<button type="button" class="fs-need fs-missing" data-need="${i}" aria-label="${escapeHtml(t("shelf.addThis", { name: filamentLabel(t, need) }))}" title="${escapeHtml(t("shelf.addThis", { name: filamentLabel(t, need) }))}">${swatch(need.color, "fs-s")}<span>${label}</span>${icon("add")}</button>`
        : `<span class="fs-need" title="${escapeHtml(t("shelf.onShelf"))}">${swatch(need.color, "fs-s")}<span>${label}</span>${icon("done")}<span class="fs-sr">${escapeHtml(t("shelf.onShelf"))}</span></span>`;
    });
    needsStrip.innerHTML = `<span class="fs-needs-title">${escapeHtml(t("shelf.forModel", { name: model.name }))}</span>${chips.join("")}<span class="fs-spacer"></span>${
      missing.size
        ? `<button type="button" class="fs-btn fs-outline fs-small" data-act="add-needed">${icon("queue")}${escapeHtml(t("shelf.addNeeded"))}</button>`
        : `<span class="fs-all-set">${icon("check")}${escapeHtml(t("shelf.allOnShelf"))}</span>`
    }`;
  }

  function showEmpty(state) {
    empty.hidden = !state;
    if (!state) return;
    $("empty-title").textContent = state.title;
    $("empty-hint").textContent = state.hint ?? "";
    $("empty-hint").hidden = !state.hint;
    const button = $("empty-act");
    button.textContent = state.label;
    button.dataset.act = state.act;
    button.className = `fs-btn ${state.act === "add" ? "fs-primary" : "fs-outline"} fs-small`;
  }

  function drawCards(spools, theirs) {
    let list = theirs;
    if (filter.material) list = list.filter((entry) => family(entry.value.material) === filter.material);
    if (filter.brand) list = list.filter((entry) => entry.value.brand.trim().toLowerCase() === filter.brand);
    if (filter.colour) list = list.filter((entry) => bucketOf(entry.value.color) === filter.colour);
    const order = new Map(everyone.map((person, i) => [person.key, i]));
    const named = (entry) => entry.value.colorName || t(`colour.${nameOf(entry.value.color)}`);
    list = list.toSorted(
      (a, b) =>
        (order.get(ownerKey(a)) ?? 99) - (order.get(ownerKey(b)) ?? 99) ||
        family(a.value.material).localeCompare(family(b.value.material)) ||
        named(a).localeCompare(named(b)) ||
        a.value.brand.localeCompare(b.value.brand),
    );
    if (!spools.length)
      showEmpty({ title: t("shelf.emptyTitle"), hint: t("shelf.emptyHint"), act: "add", label: t("shelf.add") });
    else if (!list.length) showEmpty({ title: t("shelf.noneMatch"), act: "clear", label: t("filter.clear") });
    else showEmpty(null);
    cards.hidden = !list.length;
    const keyOf = (entry) => `${ownerKey(entry)}|${entry.key}`;
    cards.replaceChildren(...list.map((entry) => card(entry, !drawn.has(keyOf(entry)))));
    drawn = new Set(list.map(keyOf));
  }

  function card(entry, enter) {
    const spool = entry.value;
    const li = document.createElement("li");
    li.className = `fs-card${entry.mine ? " fs-mine" : ""}${enter ? " fs-enter" : ""}${entry.saving ? " fs-saving" : ""}`;
    li.dataset.key = entry.key;
    const name = escapeHtml(spool.colorName || t(`colour.${nameOf(spool.color)}`));
    const lineFamily = spool.line ? family(spool.line) : null;
    const sub = escapeHtml(
      [spool.brand, spool.line, lineFamily === family(spool.material) ? "" : spool.material]
        .filter(Boolean)
        .join(" · "),
    );
    const percent = amountPercent(spool);
    const amount =
      spool.grams !== null
        ? t("amount.gramsLeft", { grams: formatGrams(spool.grams, language) })
        : spool.left
          ? t(`amount.${spool.left}`)
          : "";
    const low = spool.left === "low" || (spool.grams !== null && spool.grams < LOW_GRAMS);
    const person = everyone.find((other) => other.key === ownerKey(entry)) ?? { ...entry.user, mine: entry.mine };
    const note = escapeHtml(spool.note);
    li.innerHTML = `
      ${entry.mine ? `<button type="button" class="fs-icon-btn fs-more" aria-haspopup="menu" aria-expanded="false" aria-label="${escapeHtml(t("card.more", { name: spoolLabel(t, spool) }))}" title="${escapeHtml(t("card.moreTitle"))}">${icon("more")}</button>` : ""}
      <div class="fs-card-top">${spoolArt(spool.color)}<div class="fs-card-text"><b title="${name}">${name}</b><small title="${sub}">${sub}</small></div></div>
      ${percent === null ? "" : `<div class="fs-amount${low ? " fs-low" : ""}" aria-hidden="true"><i style="width:${percent}%"></i></div>`}
      <div class="fs-card-meta"><span class="fs-owner">${avatar(t, person)}<span>${escapeHtml(personName(t, person))}</span></span><span>${escapeHtml(amount)}</span></div>
      ${note ? `<small class="fs-card-note" title="${note}">${note}</small>` : ""}`;
    return li;
  }

  // ---- changes ----

  const putSpool = safely(async (key, value, onFailed = () => {}) => {
    const existing = entries.find((entry) => entry.mine && entry.key === key);
    const before = existing?.value;
    if (existing) Object.assign(existing, { value, saving: true });
    else
      entries.unshift({
        key,
        value,
        mine: true,
        user: reader(),
        updatedAt: new Date().toISOString(),
        cursor: "",
        saving: true,
      });
    render();
    try {
      await write(key, () => shared.set(key, value));
    } catch (error) {
      if (before) {
        const still = entries.find((entry) => entry.mine && entry.key === key);
        if (still) Object.assign(still, { value: before, saving: false });
      } else entries = entries.filter((entry) => !(entry.mine && entry.key === key));
      render();
      onFailed();
      throw error;
    }
  });

  const takeOff = safely(async (key, usedUp) => {
    const entry = entries.find((other) => other.mine && other.key === key);
    if (!entry) return;
    const name = spoolLabel(t, entry.value);
    const sure = await ui.confirm(
      usedUp
        ? { title: t("usedUp.title", { name }), message: t("usedUp.message"), confirmLabel: t("card.usedUp") }
        : {
            title: t("remove.title", { name }),
            message: t("remove.message"),
            confirmLabel: t("card.remove"),
            destructive: true,
          },
    );
    if (!sure || closed) return;
    entries = entries.filter((other) => !(other.mine && other.key === key));
    render();
    try {
      await write(key, () => shared.remove(key));
    } catch (error) {
      if (!entries.some((other) => other.mine && other.key === key)) entries = [entry, ...entries];
      render();
      throw error;
    }
  });

  // ---- menus ----

  function closeMenu({ restore = false } = {}) {
    if (!menu) return;
    const { element, opener } = menu;
    element.remove();
    menu = null;
    opener?.setAttribute("aria-expanded", "false");
    if (restore) opener?.focus();
    if (due) refreshWhenIdle();
  }

  /** Opens a menu `fill` puts the items in, under `opener` (on its left edge or right) or at a pointer. */
  function openMenu(opener, fill, { align = "left", at = null } = {}) {
    closeMenu();
    const element = document.createElement("div");
    element.className = "fs-menu";
    element.setAttribute("role", "menu");
    fill(element);
    shell.append(element);
    const frame = shell.getBoundingClientRect();
    const box = at ? { left: at.x, right: at.x, top: at.y, bottom: at.y } : opener.getBoundingClientRect();
    const wanted = at || align === "left" ? box.left - frame.left : box.right - frame.left - element.offsetWidth;
    const left = Math.max(8, Math.min(wanted, frame.width - element.offsetWidth - 8));
    let top = box.bottom - frame.top + 4;
    if (top + element.offsetHeight > frame.height - 8)
      top = Math.max(8, box.top - frame.top - element.offsetHeight - 4);
    element.style.left = `${left}px`;
    element.style.top = `${top}px`;
    opener?.setAttribute("aria-expanded", "true");
    menu = { element, opener };
    (element.querySelector('[aria-checked="true"]') ?? element.querySelector("[role^=menuitem]"))?.focus();
  }

  function menuItem(label, act, { iconName = null, danger = false, checked = null } = {}) {
    const button = document.createElement("button");
    button.type = "button";
    button.setAttribute("role", checked === null ? "menuitem" : "menuitemradio");
    if (checked !== null) button.setAttribute("aria-checked", String(checked));
    if (danger) button.className = "fs-danger";
    button.innerHTML = `${iconName ? icon(iconName) : ""}<span>${escapeHtml(label)}</span>`;
    button.addEventListener("click", () => {
      closeMenu({ restore: true });
      act();
    });
    return button;
  }

  function openCardMenu(key, opener, at = null) {
    const entry = entries?.find((other) => other.mine && other.key === key);
    if (!entry) return;
    openMenu(
      opener,
      (element) =>
        element.append(
          menuItem(t("card.edit"), () => openDialog({ key, value: entry.value }), { iconName: "edit" }),
          menuItem(t("card.usedUp"), () => takeOff(key, true), { iconName: "done" }),
          document.createElement("hr"),
          menuItem(t("card.remove"), () => takeOff(key, false), { iconName: "delete", danger: true }),
        ),
      { align: "right", at },
    );
  }

  function openColourMenu() {
    openMenu(colourButton, (element) => {
      element.append(
        menuItem(t("filter.anyColour"), () => setFilter("colour", null), {
          iconName: "palette",
          checked: !filter.colour,
        }),
      );
      const row = document.createElement("div");
      row.className = "fs-palette";
      row.setAttribute("role", "group");
      row.setAttribute("aria-label", t("filter.colour"));
      for (const [name, hex] of colours) {
        const button = menuItem("", () => setFilter("colour", name), { checked: filter.colour === name });
        button.className = "fs-swatch";
        button.style.setProperty("--fs-c", hex);
        button.setAttribute("aria-label", t(`colour.${name}`));
        button.title = t(`colour.${name}`);
        button.replaceChildren();
        row.append(button);
      }
      element.append(row);
    });
  }

  function openMoreMaterials(opener) {
    openMenu(opener, (element) =>
      element.append(
        ...moreMaterials.map(([name, count]) =>
          menuItem(`${name} · ${count}`, () => setFilter("material", name), { checked: filter.material === name }),
        ),
      ),
    );
  }

  /** Arrow keys move between a menu's items; Escape and Tab leave it. */
  function menuKeys(event) {
    const items = [...menu.element.querySelectorAll("[role^=menuitem]")];
    const at = items.indexOf(document.activeElement);
    const go = (index) => items[(index + items.length) % items.length]?.focus();
    if (event.key === "ArrowDown" || event.key === "ArrowRight") go(at + 1);
    else if (event.key === "ArrowUp" || event.key === "ArrowLeft") go(at - 1);
    else if (event.key === "Home") go(0);
    else if (event.key === "End") go(items.length - 1);
    else if (event.key === "Escape") closeMenu({ restore: true });
    else if (event.key === "Tab") return closeMenu();
    else return;
    event.preventDefault();
    event.stopPropagation();
  }

  function setFilter(name, value) {
    filter[name] = value;
    render();
  }

  // ---- the spool dialog ----

  function stateOf(spool) {
    const upper = spool.material.trim().toUpperCase();
    const choice = MATERIALS.includes(upper) ? upper : "other";
    return {
      brand: spool.brand,
      line: spool.line,
      choice,
      other: choice === "other" ? spool.material : "",
      colorName: spool.colorName,
      color: spool.color,
      hex: spool.color,
      amount: spool.grams !== null ? "grams" : spool.left,
      grams: spool.grams !== null ? String(spool.grams) : "",
      note: spool.note,
    };
  }

  function newSpool() {
    // The brand of the user's newest spool, as the next one is often the same.
    const last = spoolsOf(entries ?? []).find((entry) => entry.mine);
    return spoolValue({ brand: last?.value.brand ?? "", material: "PLA", color: "#FFFFFF", left: "full" });
  }

  function brandOptions() {
    const seen = new Map();
    for (const entry of spoolsOf(entries ?? [])) {
      const brand = entry.value.brand.trim();
      if (brand && !seen.has(brand.toLowerCase())) seen.set(brand.toLowerCase(), brand);
    }
    for (const brand of BRANDS) if (!seen.has(brand.toLowerCase())) seen.set(brand.toLowerCase(), brand);
    return [...seen.values()].map((brand) => `<option value="${escapeHtml(brand)}"></option>`).join("");
  }

  function openDialog({ key = null, value = null, queue = [] } = {}) {
    if (entries === null) return;
    closeMenu();
    const opener = root.contains(document.activeElement) ? document.activeElement : null;
    const first = value ?? (queue.length ? prefillFor(queue[0]) : newSpool());
    dialog = { key, queue: [...queue], total: queue.length, opener, state: stateOf(first) };
    fillDialog();
    veil.hidden = false;
    input("brand").focus();
  }

  function closeDialog() {
    if (!dialog) return;
    const { opener } = dialog;
    dialog = null;
    veil.hidden = true;
    (opener?.isConnected ? opener : $("add")).focus();
    if (due) refreshWhenIdle();
  }

  function showDialogColour({ typed = false } = {}) {
    const state = dialog.state;
    $("art").style.setProperty("--fs-c", state.color);
    input("native").value = state.color.toLowerCase();
    if (!typed) input("hex").value = state.hex;
    const bad = !normaliseHex(state.hex);
    input("hex").setAttribute("aria-invalid", String(bad && state.hex.trim() !== ""));
    $("hex-bad").hidden = !bad || state.hex.trim() === "";
    input("name").placeholder = t(`colour.${nameOf(state.color)}`);
    for (const button of input("palette").children)
      button.setAttribute("aria-checked", String(button.dataset.hex === state.color));
  }

  function showChoices() {
    const state = dialog.state;
    for (const button of input("material").children)
      button.setAttribute("aria-pressed", String(button.dataset.choice === state.choice));
    input("other").hidden = state.choice !== "other";
    for (const button of input("left").children)
      button.setAttribute("aria-pressed", String(button.dataset.amount === state.amount));
    $("grams").hidden = state.amount !== "grams";
  }

  function fillDialog() {
    const state = dialog.state;
    $("dialog-title").textContent = t(dialog.key ? "dialog.editTitle" : "dialog.addTitle");
    $("step").textContent =
      dialog.total > 1 ? t("dialog.step", { n: dialog.total - dialog.queue.length + 1, count: dialog.total }) : "";
    $("skip").hidden = dialog.total < 2;
    $("submit").textContent = t(dialog.key ? "dialog.save" : "dialog.add");
    $("brands").innerHTML = brandOptions();
    input("brand").value = state.brand;
    input("material").innerHTML = MATERIAL_CHOICES.map(
      (choice) =>
        `<button type="button" data-choice="${choice}" aria-pressed="false">${escapeHtml(choice === "other" ? t("dialog.other") : choice)}</button>`,
    ).join("");
    input("other").value = state.other;
    input("other").removeAttribute("aria-invalid");
    input("line").value = state.line;
    input("name").value = state.colorName;
    input("palette").innerHTML = PALETTE.map(
      ([name, hex]) =>
        `<button type="button" role="radio" aria-checked="false" data-hex="${hex}" style="--fs-c:${hex}" aria-label="${escapeHtml(t(`colour.${name}`))}" title="${escapeHtml(t(`colour.${name}`))}"></button>`,
    ).join("");
    input("left").innerHTML = AMOUNT_CHOICES.map(
      (amount) =>
        `<button type="button" data-amount="${amount}" aria-pressed="false">${escapeHtml(t(`amount.${amount}`))}</button>`,
    ).join("");
    input("grams").value = state.grams;
    input("grams").removeAttribute("aria-invalid");
    input("note").value = state.note;
    showChoices();
    showDialogColour();
  }

  /** On to the next filament the model needs, or closed after the last. */
  function advance(lastBrand) {
    dialog.queue.shift();
    if (!dialog.queue.length) return closeDialog();
    const next = prefillFor(dialog.queue[0]);
    if (!next.brand) next.brand = lastBrand;
    dialog.key = null;
    dialog.state = stateOf(next);
    fillDialog();
    body.classList.remove("fs-next");
    void body.offsetWidth;
    body.classList.add("fs-next");
    input("brand").focus();
  }

  function submitDialog() {
    const state = dialog.state;
    const material = state.choice === "other" ? state.other.trim() : state.choice;
    if (!material) {
      input("other").setAttribute("aria-invalid", "true");
      return input("other").focus();
    }
    const color = normaliseHex(state.hex);
    if (!color) {
      input("hex").setAttribute("aria-invalid", "true");
      $("hex-bad").hidden = false;
      return input("hex").focus();
    }
    let grams = null;
    if (state.amount === "grams" && state.grams.trim() !== "") {
      grams = Number(state.grams);
      if (!Number.isFinite(grams) || grams < 0 || grams > 100000) {
        input("grams").setAttribute("aria-invalid", "true");
        return input("grams").focus();
      }
    }
    const value = spoolValue({
      brand: state.brand,
      line: state.line,
      material,
      colorName: state.colorName,
      color,
      left: AMOUNTS.includes(state.amount) ? state.amount : null,
      grams,
      note: state.note,
    });
    const key = dialog.key ?? `${SPOOL}${newId()}`;
    const editing = dialog.key;
    advance(value.brand);
    // The form goes as the spool shows; should it not be saved, it comes back as it was sent, to try again.
    void putSpool(key, value, () => {
      if (!dialog && !closed) openDialog({ key: editing, value });
    });
  }

  form.addEventListener("submit", (event) => {
    event.preventDefault();
    if (dialog) submitDialog();
  });

  form.addEventListener("click", (event) => {
    const button = event.target.closest("button");
    if (!button || !dialog) return;
    const state = dialog.state;
    if (button.dataset.act === "cancel") return closeDialog();
    if (button.dataset.act === "skip") return advance(state.brand);
    if (button.dataset.choice) {
      state.choice = button.dataset.choice;
      showChoices();
      if (state.choice === "other") input("other").focus();
      return;
    }
    if (button.dataset.amount) {
      // A second press clears it: how much is left is optional.
      state.amount = state.amount === button.dataset.amount ? null : button.dataset.amount;
      showChoices();
      if (state.amount === "grams") input("grams").focus();
      return;
    }
    if (button.dataset.hex) {
      state.color = button.dataset.hex;
      state.hex = button.dataset.hex;
      showDialogColour();
    }
  });

  form.addEventListener("input", (event) => {
    if (!dialog) return;
    const state = dialog.state;
    const field = event.target;
    const text = field.value;
    if (field === input("brand")) state.brand = text;
    else if (field === input("other")) {
      state.other = text;
      field.removeAttribute("aria-invalid");
    } else if (field === input("line")) state.line = text;
    else if (field === input("name")) state.colorName = text;
    else if (field === input("note")) state.note = text;
    else if (field === input("grams")) {
      state.grams = text;
      field.removeAttribute("aria-invalid");
    } else if (field === input("hex")) {
      state.hex = text;
      state.color = normaliseHex(text) ?? state.color;
      showDialogColour({ typed: true });
    } else if (field === input("native")) {
      state.color = normaliseHex(text) ?? state.color;
      state.hex = state.color;
      showDialogColour();
    }
  });

  form.addEventListener("keydown", (event) => {
    if (event.key === "Escape") {
      event.preventDefault();
      event.stopPropagation();
      return closeDialog();
    }
    if (event.key !== "Tab") return;
    // Focus stays in the dialog while it's open.
    const stops = [...form.querySelectorAll("button, input, select, [tabindex='0']")].filter(
      (element) => !element.disabled && !element.closest("[hidden]"),
    );
    const at = stops.indexOf(document.activeElement);
    if (event.shiftKey && at <= 0) {
      event.preventDefault();
      stops.at(-1).focus();
    } else if (!event.shiftKey && at === stops.length - 1) {
      event.preventDefault();
      stops[0].focus();
    }
  });

  veil.addEventListener("pointerdown", (event) => {
    if (event.target === veil) closeDialog();
  });

  // ---- the bar, the strip and the cards ----

  peopleBar.addEventListener("click", (event) => {
    const button = event.target.closest("[data-who]");
    if (button) setFilter("who", button.dataset.who || null);
  });
  materialsBar.addEventListener("click", (event) => {
    const button = event.target.closest("button");
    if (!button) return;
    if (button.dataset.more !== undefined) return openMoreMaterials(button);
    setFilter("material", button.dataset.material || null);
  });
  brandSelect.addEventListener("change", () => setFilter("brand", brandSelect.value || null));
  colourButton.addEventListener("click", () => (menu?.opener === colourButton ? closeMenu() : openColourMenu()));

  const showAudience = (audience) => {
    $("share-label").textContent = audience.everyone
      ? t("share.everyone")
      : audience.people.length
        ? t("share.people", { count: audience.people.length })
        : t("share.onlyYou");
  };
  $("share").addEventListener(
    "click",
    safely(async () => {
      const audience = await shared.share();
      if (audience && !closed) showAudience(audience);
    }),
  );

  shell.addEventListener("click", (event) => {
    const act = event.target.closest("[data-act]")?.dataset.act;
    if (act === "add" && !event.target.closest("form")) return openDialog();
    if (act === "clear") {
      Object.assign(filter, { who: null, material: null, brand: null, colour: null });
      return render();
    }
    if (act === "retry") {
      problem = null;
      render();
      return void refresh();
    }
    if (act === "add-needed") return openDialog({ queue: missingOnShelf(needs, spoolsOf(entries ?? [])) });
  });
  needsStrip.addEventListener("click", (event) => {
    const chip = event.target.closest("[data-need]");
    if (chip) openDialog({ queue: [needs[Number(chip.dataset.need)]] });
  });
  cards.addEventListener("click", (event) => {
    const more = event.target.closest(".fs-more");
    if (!more) return;
    if (menu?.opener === more) return closeMenu();
    openCardMenu(more.closest(".fs-card").dataset.key, more);
  });
  cards.addEventListener("contextmenu", (event) => {
    const li = event.target.closest(".fs-card.fs-mine");
    if (!li) return;
    event.preventDefault();
    openCardMenu(li.dataset.key, li.querySelector(".fs-more"), { x: event.clientX, y: event.clientY });
  });

  const onOutside = (event) => {
    if (menu && !menu.element.contains(event.target) && !menu.opener?.contains(event.target)) closeMenu();
  };
  const onKey = (event) => {
    if (menu) menuKeys(event);
  };
  document.addEventListener("pointerdown", onOutside, true);
  shell.addEventListener("keydown", onKey);

  // Others' changes show up while it's open: now and then, on coming back to the window, and when a part of a model's
  // page changes something. Not while a menu, the dialog or the brand list is open; that refresh comes after.
  let due = false;
  function refreshWhenIdle() {
    due = Boolean(menu || dialog || document.activeElement === brandSelect);
    if (!due) void refresh();
  }
  const timer = setInterval(refreshWhenIdle, 30000);
  window.addEventListener("focus", refreshWhenIdle);
  const stopChanges = shared.onChange?.(refreshWhenIdle) ?? (() => {});

  labels();
  render();
  void refresh();
  void safely(async () => showAudience(await shared.audience()))();

  return () => {
    closed = true;
    closeMenu();
    clearInterval(timer);
    stopChanges();
    window.removeEventListener("focus", refreshWhenIdle);
    document.removeEventListener("pointerdown", onOutside, true);
    shell.removeEventListener("keydown", onKey);
  };
}
